def _second_mergequeue_pr(fake_gh) -> None:
    """Add a second approved-candidate issue/PR pair (124/789) to a FakeGitHub
    fixture, reviewed after the default 123/456 pair."""
    fake_gh.issues.append(
        {
            "number": 124,
            "title": "Fix parsing",
            "url": "https://example.test/issues/124",
            "body": "Parsing is broken",
            "labels": [{"name": "automated-ready"}],
            "state": "OPEN",
        }
    )
    fake_gh.prs.append(
        {
            "number": 789,
            "title": "Fix #124: parsing",
            "url": "https://example.test/pull/789",
            "headRefName": "agent/issue-124-fix-parsing",
            "baseRefName": "main",
            "headRefOid": "sha-def789",
            "mergeStateStatus": "CLEAN",
            "body": "Closes #124\n\nTests: regression coverage added.",
            "labels": [],
            "isCrossRepository": False,
            "state": "OPEN",
        }
    )


def test_merge_ready_mergequeue_parked_pr_excluded_from_merge_train_head(
    tmp_path: Path,
) -> None:
    """Adversarial review finding #1a: once PR #456 is parked in Aviator's
    queue (state status 'mergequeue'), it must not keep winning
    front-of-train's merge-train head on every subsequent poll — Aviator now
    owns its serialization. Without excluding 'mergequeue'-status PRs from
    _merge_train_candidates, #456 (reviewed first, still approved, still
    head-SHA-matching) would win merge-train head forever and PR #789 would
    never be attempted, even though #789 is independently approved and green."""
    config = OrchestratorConfig(auto_merge=_mergequeue_automerge())
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    _second_mergequeue_pr(fake_gh)
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")
    app.record_review(789, "approved", summary="ok")

    # First poll: 456 was reviewed first (and sorts first on a tie), so it
    # wins merge-train head and gets parked into the mergequeue.
    first = app.merge_ready(456, merge=True)
    assert first.data["can_merge"] is True
    assert first.data["mergequeue_label_applied"] is True
    assert (456, "mergequeue") in fake_gh.pr_labels_added

    # Second poll: 789 must now become merge-train head. Before the fix, 456
    # (still "approved" + head-SHA-matching from _merge_train_candidates'
    # point of view) keeps winning head, so 789 gets bounced as "not the
    # head of the merge-train queue" (can_merge False) forever.
    second = app.merge_ready(789, merge=True)
    assert second.data["can_merge"] is True
    assert second.data["mergequeue_label_applied"] is True
    assert (789, "mergequeue") in fake_gh.pr_labels_added


def test_merge_train_candidates_no_state_read_when_mergequeue_label_unset(
    tmp_path: Path,
    monkeypatch,
) -> None:
    """Issue #421: when auto_merge.mergequeue_label is None (the default),
    _merge_train_candidates must not call load_state_locked. The mergequeue
    handoff feature is disabled, so no PR can have status 'mergequeue' and the
    state read is pure hot-path overhead that widens the StateLockBusy window.
    """
    config = OrchestratorConfig(auto_merge=_approved_automerge())
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")

    def _fail_if_called(*_args, **_kwargs):
        raise AssertionError("load_state_locked called with mergequeue_label unset")

    monkeypatch.setattr("charlie_work.workflow.load_state_locked", _fail_if_called)

    candidates = app._merge_train_candidates(prs=fake_gh.prs)

    pr_numbers = [pr_number for _sort_key, pr_number, _pr, _decision, _head in candidates]
    assert 456 in pr_numbers


def test_merge_ready_mergequeue_parked_pr_skips_charlie_branch_sync(
    tmp_path: Path,
) -> None:
    """Adversarial review finding #1b: once a PR is parked in Aviator's queue
    (state status 'mergequeue'), charlie must stop calling pr_update_branch
    for it on every subsequent poll — Aviator now owns rebasing queued PRs.
    This repo's live orchestrator.config.yaml sets update_open_prs: true
    (broadcast), so without this fix charlie would race Aviator's own rebase
    as a second writer on the same ref on every poll while the base is stale."""
    config = OrchestratorConfig(auto_merge=_mergequeue_automerge())
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")

    # First poll parks the PR.
    first = app.merge_ready(456, merge=True)
    assert first.data["mergequeue_label_applied"] is True
    assert load_state(paths.state_file)["prs"]["456"]["status"] == "mergequeue"

    # Simulate main having advanced past this PR's merge-base — a stale base,
    # exactly as would happen once Aviator (or anything else) merges another
    # PR into main while #456 sits in the queue.
    fake_gh.compare_overrides[("main", "sha-abc123")] = {
        "base_commit": {"sha": "new-main-tip"},
        "merge_base_commit": {"sha": "stale-ancestor"},
    }

    second = app.merge_ready(456, merge=True)

    assert second.data["can_merge"] is False
    assert fake_gh.pr_update_branch_calls == []


def test_merge_ready_mergequeue_label_add_failure_does_not_advance_status(
    tmp_path: Path,
) -> None:
    """Adversarial review finding #2: add_pr_label IS the entire handoff. A
    failed label add must not be silently treated like a best-effort cleanup
    step — it must not advance state to 'mergequeue' (that would orphan the
    PR: never self-merged, never picked up by Aviator, and nothing would ever
    look wrong to state). It must instead increment
    consecutive_failed_merge_attempts (so the failure retries and can
    escalate) and surface the failure in the result message."""
    config = OrchestratorConfig(auto_merge=_mergequeue_automerge())
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    fake_gh.add_pr_label_ok = False
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")

    result = app.merge_ready(456, merge=True)

    assert result.data["can_merge"] is True
    assert result.data["mergequeue_label_applied"] is False
    assert (456, "mergequeue") in fake_gh.pr_labels_added  # attempted
    assert fake_gh.merged == []
    assert "FAILED to apply" in result.message
    persisted = load_state(paths.state_file)["prs"]["456"]
    assert persisted["status"] == "approved"
    assert persisted["status"] != "mergequeue"
    assert persisted["consecutive_failed_merge_attempts"] == 1


def test_merge_ready_mergequeue_label_add_failure_alarm_fires_at_threshold(
    tmp_path: Path,
) -> None:
    """The failed-attempt alarm must be able to fire for a handoff-label
    failure too. Before this fix, can_merge is True whenever checks are green
    and the PR is approved (that is the whole point of reaching the
    mergequeue branch), so the pre-existing 'approved and not can_merge'
    alarm gate could never trigger for a persistently failing label add — a
    typo'd label or a missing repo label would retry forever with zero
    escalation."""
    from charlie_work.config import AutoMergeConfig

    config = OrchestratorConfig(
        auto_merge=AutoMergeConfig(
            required_checks=(),
            require_approved_review=True,
            mergequeue_label="mergequeue",
            failed_attempt_alarm=2,
        )
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    fake_gh.add_pr_label_ok = False
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")

    first = app.merge_ready(456, merge=True)
    assert first.data["merge_attempt_alarm"] is False
    assert first.data["consecutive_failed_merge_attempts"] == 1

    second = app.merge_ready(456, merge=True)
    assert second.data["merge_attempt_alarm"] is True
    assert second.data["consecutive_failed_merge_attempts"] == 2
    assert "mergequeue" in (second.data["merge_attempt_warning"] or "")


def test_merge_ready_mergequeue_silent_revert_increments_counter_across_passes(
    tmp_path: Path,
) -> None:
    """Issue #823: Aviator can accept the mergequeue label POST and then
    asynchronously strip it 2-3 seconds later (draft PR, failing required
    check, base mismatch, paused queue, ...). add_pr_label's boolean return
    only proves the POST succeeded, so a silent revert must be detected
    cross-pass (existing_pr_state's prior status vs. this pass's live
    labels) and must INCREMENT consecutive_failed_merge_attempts, never
    reset it. A single-pass test would still pass throughout the entire live
    incident this issue documents (PRs #690/#700, 2026-07-31) and is
    explicitly insufficient per the issue's acceptance criteria -- this
    drives three consecutive passes and asserts the counter actually climbs
    (0, 1, 2), which also empirically exercises the ordering hazard between
    the handoff-success zeroing write and the failed-attempt-alarm
    increment: without guarding the zeroing on mergequeue_label_reverted,
    every reverted pass would read a false 0 baseline and the sequence would
    be 0, 1, 1 instead."""
    config = OrchestratorConfig(auto_merge=_mergequeue_automerge())
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")

    # Pass 1: fresh handoff, succeeds. Counter starts/stays at 0.
    first = app.merge_ready(456, merge=True)
    assert first.data["mergequeue_label_applied"] is True
    assert first.data["consecutive_failed_merge_attempts"] == 0
    assert load_state(paths.state_file)["prs"]["456"]["status"] == "mergequeue"

    # FakeGitHub.add_pr_label only logs the call -- it never mutates
    # fake_gh.prs[0]["labels"] -- so the live PR the next pass observes
    # already shows the label absent, exactly like a real Aviator revert.
    #
    # Pass 2: existing_pr_state.status == "mergequeue" from pass 1, live
    # label absent -> reverted. The re-add attempt succeeds again this pass
    # (mergequeue_label_applied True), but the counter must climb to 1, not
    # reset to 0.
    second = app.merge_ready(456, merge=True)
    assert second.data["mergequeue_label_applied"] is True
    assert second.data["consecutive_failed_merge_attempts"] == 1
    assert second.data["merge_attempt_alarm"] is False

    # Pass 3: reverted again -> counter keeps climbing, not stuck at 1.
    third = app.merge_ready(456, merge=True)
    assert third.data["mergequeue_label_applied"] is True
    assert third.data["consecutive_failed_merge_attempts"] == 2
    assert third.data["merge_attempt_alarm"] is False


def test_merge_ready_mergequeue_silent_revert_escalation_reachable(tmp_path: Path) -> None:
    """Issue #823 acceptance criterion 3: after the configured number of
    consecutive reverted mergequeue handoffs, the PR must escalate exactly
    as an outright add_pr_label failure already does -- the same shared
    consecutive_failed_merge_attempts counter crossing the same
    failed_attempt_alarm threshold, no new parallel alarm mechanism."""
    from charlie_work.config import AutoMergeConfig

    config = OrchestratorConfig(
        auto_merge=AutoMergeConfig(
            required_checks=(),
            require_approved_review=True,
            mergequeue_label="mergequeue",
            failed_attempt_alarm=2,
        )
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")

    first = app.merge_ready(456, merge=True)
    assert first.data["merge_attempt_alarm"] is False
    assert first.data["consecutive_failed_merge_attempts"] == 0

    second = app.merge_ready(456, merge=True)
    assert second.data["merge_attempt_alarm"] is False
    assert second.data["consecutive_failed_merge_attempts"] == 1

    third = app.merge_ready(456, merge=True)
    assert third.data["merge_attempt_alarm"] is True
    assert third.data["consecutive_failed_merge_attempts"] == 2


def test_merge_ready_mergequeue_label_present_next_pass_not_treated_as_reverted(
    tmp_path: Path,
) -> None:
    """Regression guard: a PR whose mergequeue label IS still present on the
    live PR the next pass is the normal healthy path and must not be
    misdetected as a silent revert -- the counter must stay at 0 and no
    alarm must fire."""
    config = OrchestratorConfig(auto_merge=_mergequeue_automerge())
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")

    first = app.merge_ready(456, merge=True)
    assert first.data["consecutive_failed_merge_attempts"] == 0
    assert load_state(paths.state_file)["prs"]["456"]["status"] == "mergequeue"

    # The label genuinely survived to the next pass -- simulate the live PR
    # actually carrying it (unlike add_pr_label, which is a call log, not a
    # label mutation on the fake).
    fake_gh.prs[0]["labels"] = [{"name": "mergequeue"}]

    second = app.merge_ready(456, merge=True)
    assert second.data["mergequeue_label_applied"] is True
    assert second.data["consecutive_failed_merge_attempts"] == 0
    assert second.data["merge_attempt_alarm"] is False
    assert load_state(paths.state_file)["prs"]["456"]["status"] == "mergequeue"


def test_merge_ready_mergequeue_revert_detector_ignores_non_mergequeue_prior_status(
    tmp_path: Path,
) -> None:
    """Issue #823 acceptance criterion 4: existing_pr_state empty, or with a
    status other than 'mergequeue', must never trip the revert detector --
    only a PRIOR pass that itself recorded status == 'mergequeue' is
    eligible. Seeds a plausible non-mergequeue prior status (freshly
    approved, never yet handed off) to prove the detector keys off
    status == 'mergequeue' specifically, not merely 'some prior state
    exists'."""
    config = OrchestratorConfig(auto_merge=_mergequeue_automerge())
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")

    seed = load_state(paths.state_file)
    seed["prs"]["456"] = {
        "status": "approved",
        "issue_number": 123,
        "consecutive_failed_merge_attempts": 0,
    }
    save_state(paths.state_file, seed)

    result = app.merge_ready(456, merge=True)

    assert result.data["mergequeue_label_applied"] is True
    assert result.data["consecutive_failed_merge_attempts"] == 0
    assert result.data["merge_attempt_alarm"] is False
    assert load_state(paths.state_file)["prs"]["456"]["status"] == "mergequeue"


def test_merge_ready_mergequeue_check_failure_still_routes_to_rework(tmp_path: Path) -> None:
    """Issue #823 (advisor-flagged gap): a silent revert caused by a genuine
    required-check failure must still reach check-failure-rework dispatch,
    not be shadowed by mergequeue_label_reverted.

    A prior pass's successful handoff leaves existing_pr_state.status ==
    "mergequeue". If a required check then goes red and Aviator strips the
    label for cause, the naive fold-in (mergequeue_label_reverted OR'd into
    mergequeue_handoff_failed with no other condition) makes
    mergequeue_handoff_failed True purely from the carried-over status. That
    would shadow the check-failure-rework dispatch gate's `not
    mergequeue_handoff_failed` term (workflow.py) and permanently block
    rework for a PR whose check failure is exactly the fixable thing rework
    exists for -- a strictly worse outcome than pre-#823 behavior. The revert
    term is gated on can_merge so a real check failure (can_merge False for a
    reason unrelated to the handoff) is still attributed and routed as a
    check failure. Proven behaviorally: the check-failure-rework dispatch
    (issue_status -> rework_requested, check_failure_rework_requested event)
    only fires when mergequeue_handoff_failed is False, so its firing here is
    direct proof the gate was not shadowed."""
    from charlie_work.config import AutoMergeConfig, DevinConfig

    required = ("Tests passed", "Lint & Format", "Pre-commit")
    config = OrchestratorConfig(
        auto_merge=AutoMergeConfig(
            required_checks=required,
            require_approved_review=True,
            mergequeue_label="mergequeue",
            failed_attempt_alarm=1,
        ),
        devin=DevinConfig(adapter="command", dispatch_command="exit 0"),
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHubWithChecks(
        checks=[{"name": name, "state": "SUCCESS"} for name in required]
    )
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)
    app.record_review(456, "approved", summary="ok")

    # Pass 1: checks green, handoff succeeds, status becomes "mergequeue".
    first = app.merge_ready(456, merge=True)
    assert first.data["mergequeue_label_applied"] is True
    assert load_state(paths.state_file)["prs"]["456"]["status"] == "mergequeue"

    # Pass 2: a required check genuinely fails. FakeGitHub.add_pr_label never
    # mutates fake_gh.prs[0]["labels"], so the live PR this pass already
    # shows the mergequeue label absent -- indistinguishable, from the
    # detector's point of view, from Aviator stripping it for cause. can_merge
    # is False this pass because of the real check failure, not a handoff
    # problem.
    fake_gh.checks = [
        {"name": "Tests passed", "state": "FAILURE"},
        {"name": "Lint & Format", "state": "SUCCESS"},
        {"name": "Pre-commit", "state": "SUCCESS"},
    ]
    second = app.merge_ready(456, merge=True)

    assert second.data["can_merge"] is False
    assert second.data["checks"]["failed"] == ("Tests passed",)
    assert second.data["merge_attempt_alarm"] is True

    state = load_state(paths.state_file)
    assert state["issues"]["123"]["status"] == "rework_requested"
    assert state["prs"]["456"]["status"] == "rework_requested"
    check_failure_events = [
        e for e in state["events"] if e["kind"] == "check_failure_rework_requested"
    ]
    assert len(check_failure_events) == 1
    assert check_failure_events[0]["payload"]["pr_number"] == 456
    assert check_failure_events[0]["payload"]["issue_number"] == 123
    assert check_failure_events[0]["payload"]["failed_checks"] == ["Tests passed"]


def test_linked_issue_number_rejects_bare_hash_in_attacker_title() -> None:
    # A bare #N substring in an attacker-controlled title must NOT bind the PR
    # to issue N (label/merge hijack). Only a closing keyword counts.
    assert (
        linked_issue_number(
            {"title": "Refactor everything #1 nicely"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        is None
    )
    assert (
        linked_issue_number(
            {"title": "see #5 for context", "body": "no link"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        is None
    )
    # Closing-keyword forms still resolve.
    assert (
        linked_issue_number(
            {"title": "Fix #321: thing"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        == 321
    )
    assert (
        linked_issue_number(
            {"body": "Resolves #7"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        == 7
    )
    # Orchestrator's own branch convention is the trusted head-ref signal.
    assert (
        linked_issue_number(
            {"headRefName": "agent/issue-456-x", "title": "#999"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        == 456
    )


def test_linked_issue_number_fork_pr_branch_name_does_not_bind() -> None:
    # Issue #9: Fork PRs must not bind via branch name (attacker-controlled).
    # A fork PR with branch name "issue-42" should NOT bind to issue 42.
    assert (
        linked_issue_number(
            {"headRefName": "issue-42-fix"},
            is_cross_repository=True,
            branch_prefix="agent/issue",
        )
        is None
    )
    # Even with the orchestrator's prefix, fork PRs must not bind via branch.
    assert (
        linked_issue_number(
            {"headRefName": "agent/issue-42-fix"},
            is_cross_repository=True,
            branch_prefix="agent/issue",
        )
        is None
    )


def test_linked_issue_number_same_repo_branch_with_prefix_binds() -> None:
    # Issue #9: Same-repo PRs with correct branch prefix should still bind.
    assert (
        linked_issue_number(
            {"headRefName": "agent/issue-42-fix"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        == 42
    )
    # Same-repo PR with wrong prefix should not bind via branch.
    assert (
        linked_issue_number(
            {"headRefName": "issue-42-fix"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        is None
    )


def test_linked_issue_number_fork_pr_closing_keyword_does_not_bind() -> None:
    # Issue #9: Fork PRs must NOT bind via closing keywords for lifecycle purposes.
    # (GitHub's own auto-close on merge is GitHub's policy for issue state;
    # the orchestrator's label lifecycle is ours.)
    assert (
        linked_issue_number(
            {"body": "Closes #42"},
            is_cross_repository=True,
            branch_prefix="agent/issue",
        )
        is None
    )
    assert (
        linked_issue_number(
            {"title": "Fix #42: security issue"},
            is_cross_repository=True,
            branch_prefix="agent/issue",
        )
        is None
    )


def test_linked_issue_number_same_repo_closing_keyword_binds() -> None:
    # Same-repo PRs should still bind via closing keywords.
    assert (
        linked_issue_number(
            {"body": "Closes #42"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        == 42
    )
    assert (
        linked_issue_number(
            {"title": "Fix #42: security issue"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        == 42
    )


def test_linked_issue_number_none_treats_as_cross_repository() -> None:
    # When is_cross_repository is None (provenance unknown), treat as cross-repo
    # for trust purposes — bind nothing via branch name or closing keyword
    # (fail closed). This hardens against future call sites that omit the
    # parameter or pass a PR dict missing the isCrossRepository field.
    assert (
        linked_issue_number(
            {"headRefName": "agent/issue-42-fix"},
            is_cross_repository=None,
            branch_prefix="agent/issue",
        )
        is None
    )
    assert (
        linked_issue_number(
            {"body": "Closes #42"},
            is_cross_repository=None,
            branch_prefix="agent/issue",
        )
        is None
    )


def test_linked_issue_number_negation_guard_rejects_negated_keyword() -> None:
    # Issue #781 AC1: a closing keyword preceded by a negation must not
    # bind -- "does not fix #649" is the real-world PR #766 -> issue #649
    # text that produced a false LABEL TRANSITION (not a GitHub auto-close;
    # this guard only affects charlie-work's own binding). The non-negated
    # form of the identical keyword still binds.
    assert (
        linked_issue_number(
            {"body": "does not fix #649"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        is None
    )
    assert (
        linked_issue_number(
            {"body": "Fixes #649"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        == 649
    )


def test_linked_issue_number_negation_guard_table() -> None:
    # Issue #781 AC2: table-driven negation coverage (doesn't / never /
    # without / cannot / does not), plus non-negated controls proving the
    # guard doesn't over-trigger on unrelated text.
    negated_cases = [
        "doesn't close #1",
        "never resolves #2",
        # "without fixing #3" returns None via the BASE regex, not the
        # negation guard: _CLOSING_KEYWORD_REF only matches fix/fixes/fixed
        # (fix(?:e[sd])?) -- never the gerund "fixing". Included per the
        # issue's explicit list, but see the dedicated assertion below for
        # proof this is NOT evidence the negation guard itself fired.
        "without fixing #3",
        "cannot close #4",
        "does not fix #5",
    ]
    for body in negated_cases:
        assert (
            linked_issue_number(
                {"body": body},
                is_cross_repository=False,
                branch_prefix="agent/issue",
            )
            is None
        ), f"expected no binding for negated text: {body!r}"

    # Non-negated controls: the same keywords, without a preceding negation,
    # still bind -- proves the guard isn't simply matching nothing.
    non_negated_cases = [
        ("Closes #1", 1),
        ("This resolves #2", 2),
        ("Fixes #5", 5),
    ]
    for body, expected in non_negated_cases:
        assert (
            linked_issue_number(
                {"body": body},
                is_cross_repository=False,
                branch_prefix="agent/issue",
            )
            == expected
        ), f"expected binding to {expected} for non-negated text: {body!r}"

    # "fixing #3" alone (no negation at all) confirms the gerund truly never
    # matches the base regex -- so the None result above for "without
    # fixing #3" is not evidence the negation guard fired.
    assert (
        linked_issue_number(
            {"body": "fixing #3"},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        is None
    )


def test_linked_issue_number_negation_does_not_shadow_later_genuine_match() -> None:
    # A negated match earlier in a text field must not prevent a later,
    # genuine closing keyword from binding -- finditer-continuation, not
    # search()-first-match-only. Monotone with respect to pre-#781 behavior:
    # no input that previously returned a number now returns None because of
    # this change; the negation guard can only turn a previously-binding
    # negated match into None, never suppress a separate genuine one.
    #
    # The negation lookback window (32 chars, chosen to cover "does not "
    # plus headroom) is deliberately wide enough to span a short clause, so
    # a genuine match must sit outside that window to prove continuation
    # rather than an accidental non-negation coincidence. Verified
    # empirically: without the padding, "does not fix #649. Fixes #700"
    # actually returns None (the 32-char window reaches back across the
    # sentence boundary to "not") -- that cross-sentence over-triggering is
    # the deliberate, sanctioned safe-direction tradeoff described on
    # `_NEGATION_LOOKBEHIND_CHARS`, not a bug. This test instead places the
    # genuine match far enough away to isolate the continuation behavior.
    padded_body = "does not fix #649. " + ("x" * 50) + " Fixes #700"
    assert (
        linked_issue_number(
            {"body": padded_body},
            is_cross_repository=False,
            branch_prefix="agent/issue",
        )
        == 700
    )


def test_rework_cap_survives_event_log_truncation(tmp_path: Path) -> None:
    # The P0: the counter used to derive from state["events"], which
    # append_event truncates to the last 200 - evicting a PR's earlier
    # request_changes and silently resetting the cap. The durable per-PR
    # counter must escalate regardless of how many unrelated events churn.
    from charlie_work.state import append_event as _append

    config = OrchestratorConfig()  # max_rework_cycles = 2
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    # First request_changes (count = 1, head = "sha-1")
    fake_gh.pr_head_shas[456] = "sha-1"
    app.record_review(456, "request_changes", summary="a")

    # Second request_changes (count = 2, head = "sha-2")
    fake_gh.pr_head_shas[456] = "sha-2"
    app.record_review(456, "request_changes", summary="b")

    # Flood the event log so any record_review events for 456 are evicted.
    state = load_state(paths.state_file)
    for i in range(300):
        state = _append(state, "review_packet", {"pr_number": 90000 + i}, max_size=200)
    save_state(paths.state_file, state)
    assert not any(  # prove the earlier request_changes events are gone
        e.get("kind") == "record_review" for e in load_state(paths.state_file)["events"]
    )

    # Third request_changes (count stays at 2, escalated, head = "sha-3")
    fake_gh.pr_head_shas[456] = "sha-3"
    third = app.record_review(456, "request_changes", summary="c")

    assert third.data["escalated"] is True
    assert third.data["rework_path"] is None
    assert (123, "agent:human-needed") in fake_gh.labels_added


