def test_maybe_reclaim_worktrees_dry_run_threads_and_removes_nothing(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """A --dry-run fleet pass must run the sweep in preview mode, which removes
    nothing (the preview-vs-act class tracked in #614-#619). ``dry_run`` is
    threaded from the app into ``clean_worktrees``."""
    from charlie_work import workflow as workflow_module
    from charlie_work.worktree import WorktreeCleanResult

    app = _reclamation_app(tmp_path, dry_run=True)

    calls: list[dict] = []

    def _fake_clean(*args: object, **kwargs: object) -> WorktreeCleanResult:
        calls.append({"args": args, "kwargs": kwargs})
        return WorktreeCleanResult(
            ok=True,
            message="worktree-clean (dry-run): 2 eligible, 0 skipped, 0 orphan(s)",
            data={
                "planned": [{"worktree": "a"}, {"worktree": "b"}],
                "removed": [],
                "skipped": [],
                "failed": [],
                "orphans": {"planned": [], "removed": [], "failed": []},
                "venv_ok": True,
                "venv_message": "ok",
                "attention_events": [],
            },
        )

    monkeypatch.setattr(workflow_module, "clean_worktrees", _fake_clean)

    summary = app._maybe_reclaim_worktrees()

    assert summary is not None
    assert len(calls) == 1
    # dry_run is threaded honestly into the sweep.
    assert calls[0]["kwargs"]["dry_run"] is True
    # The canonical resolved worktrees root is passed -- not a manual
    # re-derivation -- so this call site can never diverge from dispatch's
    # and `charlie worktree-clean`'s (the create/sweep split documented in
    # layout.py's module docstring, "74-uncollected-worktrees").
    assert calls[0]["args"][1] == app.layout.worktrees
    # A preview removes nothing.
    assert summary["removed"] == 0
    assert summary["planned"] == 2
    assert summary["dry_run"] is True
    # The schedule is advanced even in dry-run: clean_worktrees makes its
    # live `gh pr view` fan-out unconditionally (dry_run only gates the final
    # `git worktree remove`), so the cadence gate's cost is identical in both
    # modes and must be rate-limited in both.
    state = load_state(app.paths.state_file)
    assert state["worktree_reclamation"]["next_run_at"] is not None
    # An event was emitted so the preview is observable.
    events = [e for e in state["events"] if e["kind"] == "worktrees_reclaimed"]
    assert len(events) == 1
    assert events[0]["payload"]["dry_run"] is True
    assert events[0]["payload"]["planned"] == 2
    assert events[0]["payload"]["removed"] == 0


def test_maybe_reclaim_worktrees_runs_and_emits_event(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """A live (non-dry-run) pass runs the sweep, records a
    ``worktrees_reclaimed`` event with the counts, and advances the cadence
    schedule (issue #636: a maintenance action that leaves no trace is
    indistinguishable from one that never ran -- lesson from #595/#621)."""
    from datetime import UTC, datetime

    from charlie_work import workflow as workflow_module
    from charlie_work.worktree import WorktreeCleanResult

    app = _reclamation_app(tmp_path, interval_minutes=60)

    def _fake_clean(*_args: object, **_kwargs: object) -> WorktreeCleanResult:
        return WorktreeCleanResult(
            ok=True,
            message="worktree-clean: 3 removed, 1 skipped, 0 failed, 0 orphan(s)",
            data={
                "planned": [],
                "removed": [{"issue_number": 1}, {"issue_number": 2}, {"issue_number": 3}],
                "skipped": [{"issue_number": 4}],
                "failed": [],
                "orphans": {"planned": [], "removed": [], "failed": []},
                "venv_ok": True,
                "venv_message": "ok",
                "attention_events": [],
            },
        )

    monkeypatch.setattr(workflow_module, "clean_worktrees", _fake_clean)

    # frozen_now (issue #828) injected so the schedule assertion below is
    # exact instead of racing the sweep's own duration (or a CI stall
    # between the schedule computation and this assertion). No downstream
    # real-clock dependency follows in this test, so no offset is needed.
    frozen_now = datetime.now(UTC)
    summary = app._maybe_reclaim_worktrees(now=frozen_now)

    assert summary is not None
    assert summary["dry_run"] is False
    assert summary["removed"] == 3
    assert summary["skipped"] == 1
    state = load_state(app.paths.state_file)
    events = [e for e in state["events"] if e["kind"] == "worktrees_reclaimed"]
    assert len(events) == 1
    assert events[0]["payload"]["removed"] == 3
    # The schedule was advanced ~interval_minutes into the future, so the very
    # next pass does not re-fire the per-candidate gh fan-out.
    next_run_at = state["worktree_reclamation"]["next_run_at"]
    expected = (
        (frozen_now + timedelta(minutes=60))
        .replace(microsecond=0)
        .isoformat()
        .replace("+00:00", "Z")
    )
    assert next_run_at == expected


def test_maybe_reclaim_worktrees_event_carries_skip_reasons(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """Issue #1012: ``clean_worktrees`` computes a distinct ``reason`` string
    per skipped worktree, but only ``len(skipped)`` used to reach the durable
    ``worktrees_reclaimed`` event. The full reason strings, plus the
    out-of-scope/registered counts, must now survive into the persisted
    payload -- an operator reading events.db, not live output, is the actual
    consumer this event exists for."""
    from charlie_work import workflow as workflow_module
    from charlie_work.worktree import WorktreeCleanResult

    app = _reclamation_app(tmp_path, interval_minutes=60)

    skipped_entries = [
        {
            "worktree": "C:/wt/agent-issue-4",
            "branch": "agent/issue-4",
            "issue_number": 4,
            "pr_number": 40,
            "reason": "worktree HEAD (abc12345) is not contained in merged PR "
            "head (def67890); stray post-merge commit(s)",
        },
        {
            "worktree": "C:/wt/agent-issue-5",
            "branch": "agent/issue-5",
            "issue_number": 5,
            "pr_number": 50,
            "reason": "live worker detected: recorded PID 1234 is alive",
        },
    ]

    def _fake_clean(*_args: object, **_kwargs: object) -> WorktreeCleanResult:
        return WorktreeCleanResult(
            ok=True,
            message="worktree-clean: 0 removed, 2 skipped, 0 failed, 0 orphan(s)",
            data={
                "planned": [],
                "removed": [],
                "skipped": skipped_entries,
                "failed": [],
                "orphans": {"planned": [], "removed": [], "failed": []},
                "venv_ok": True,
                "venv_message": "ok",
                "attention_events": [],
                "worktrees_registered": 3,
                "worktrees_out_of_scope": 1,
            },
        )

    monkeypatch.setattr(workflow_module, "clean_worktrees", _fake_clean)

    summary = app._maybe_reclaim_worktrees()

    assert summary is not None
    assert summary["skipped"] == 2
    # The exact reason strings -- not just a count -- reach the summary.
    assert summary["skipped_examples"] == skipped_entries
    assert summary["worktrees_registered"] == 3
    assert summary["worktrees_out_of_scope"] == 1

    state = load_state(app.paths.state_file)
    events = [e for e in state["events"] if e["kind"] == "worktrees_reclaimed"]
    assert len(events) == 1
    payload = events[0]["payload"]
    # This is the load-bearing assertion: the durable event -- not just the
    # in-memory summary -- carries the reasons. Before this fix, `payload`
    # had no `skipped_examples` key at all.
    assert payload["skipped_examples"] == skipped_entries
    assert "stray post-merge commit(s)" in payload["skipped_examples"][0]["reason"]
    assert "live worker detected" in payload["skipped_examples"][1]["reason"]
    assert payload["worktrees_out_of_scope"] == 1

    # The issue's actual complaint is that reconstructing "why" from events.db
    # was impossible -- state.json's 200-entry array is a convenience cache,
    # not the durable store an operator queries after the fact. Round-trip
    # through the real SQLite dual-write (append_event -> events.db) via the
    # same query_events() helper an operator would use, not just state.json.
    db_events = query_events(app.paths.state_file, kind="worktrees_reclaimed")
    assert len(db_events) == 1
    db_payload = db_events[0]["payload"]
    assert db_payload["skipped_examples"] == skipped_entries
    assert "stray post-merge commit(s)" in db_payload["skipped_examples"][0]["reason"]
    assert "live worker detected" in db_payload["skipped_examples"][1]["reason"]
    assert db_payload["worktrees_out_of_scope"] == 1
    assert db_payload["worktrees_registered"] == 3


def test_maybe_reclaim_worktrees_skip_examples_truncated(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """A standing backlog of skipped worktrees must not re-emit every reason
    string into events.db on every cadence interval -- the same idiom as
    ``_MAX_DEFERRED_CONCURRENCY_EXAMPLES`` (issue #1005). ``skipped`` stays
    the exact count; ``skipped_examples`` is capped."""
    from charlie_work import workflow as workflow_module
    from charlie_work.workflow import _MAX_SKIPPED_WORKTREE_EXAMPLES
    from charlie_work.worktree import WorktreeCleanResult

    app = _reclamation_app(tmp_path, interval_minutes=60)

    many_skipped = [
        {
            "worktree": f"C:/wt/agent-issue-{i}",
            "branch": f"agent/issue-{i}",
            "issue_number": i,
            "pr_number": i * 10,
            "reason": "PR not merged",
        }
        for i in range(_MAX_SKIPPED_WORKTREE_EXAMPLES + 7)
    ]

    def _fake_clean(*_args: object, **_kwargs: object) -> WorktreeCleanResult:
        return WorktreeCleanResult(
            ok=True,
            message="worktree-clean: 0 removed, many skipped, 0 failed, 0 orphan(s)",
            data={
                "planned": [],
                "removed": [],
                "skipped": many_skipped,
                "failed": [],
                "orphans": {"planned": [], "removed": [], "failed": []},
                "venv_ok": True,
                "venv_message": "ok",
                "attention_events": [],
                "worktrees_registered": len(many_skipped) + 1,
                "worktrees_out_of_scope": 1,
            },
        )

    monkeypatch.setattr(workflow_module, "clean_worktrees", _fake_clean)

    summary = app._maybe_reclaim_worktrees()

    assert summary is not None
    # The exact count is never truncated.
    assert summary["skipped"] == len(many_skipped)
    # The examples list IS truncated.
    assert len(summary["skipped_examples"]) == _MAX_SKIPPED_WORKTREE_EXAMPLES
    assert summary["skipped_examples"] == many_skipped[:_MAX_SKIPPED_WORKTREE_EXAMPLES]

    state = load_state(app.paths.state_file)
    events = [e for e in state["events"] if e["kind"] == "worktrees_reclaimed"]
    assert len(events[0]["payload"]["skipped_examples"]) == _MAX_SKIPPED_WORKTREE_EXAMPLES
    assert events[0]["payload"]["skipped"] == len(many_skipped)


def test_maybe_reclaim_worktrees_advances_schedule_before_sweep(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """The schedule is advanced BEFORE the sweep runs, so a sweep that errors
    or takes longer than one poll interval cannot double-fire on the next
    pass."""
    from charlie_work import workflow as workflow_module
    from charlie_work.worktree import WorktreeCleanResult

    app = _reclamation_app(tmp_path, interval_minutes=60)

    def _exploding_clean(*_args: object, **_kwargs: object) -> WorktreeCleanResult:
        # Simulate a sweep that fails: the schedule must already have been
        # advanced before this point.
        state = load_state(app.paths.state_file)
        assert state["worktree_reclamation"]["next_run_at"] is not None
        return WorktreeCleanResult(
            ok=False,
            message="worktree-clean: 0 removed, 0 skipped, 1 failed",
            data={
                "planned": [],
                "removed": [],
                "skipped": [],
                "failed": [{"worktree": "a"}],
                "orphans": {"planned": [], "removed": [], "failed": []},
                "venv_ok": True,
                "venv_message": "ok",
                "attention_events": [],
            },
        )

    monkeypatch.setattr(workflow_module, "clean_worktrees", _exploding_clean)

    summary = app._maybe_reclaim_worktrees()

    assert summary is not None
    assert summary["ok"] is False
    assert summary["failed"] == 1
    # A failed sweep still records an event (observability) and keeps the
    # advanced schedule (no immediate retry storm).
    state = load_state(app.paths.state_file)
    assert state["worktree_reclamation"]["next_run_at"] is not None
    events = [e for e in state["events"] if e["kind"] == "worktrees_reclaimed"]
    assert len(events) == 1
    assert events[0]["payload"]["failed"] == 1


def _reconcile_pass_app(
    tmp_path: Path,
    *,
    interval_minutes: int = 30,
    enabled: bool = True,
    gh: Any = None,
) -> OrchestratorApp:
    from charlie_work.config import ReconcilePassConfig

    config = OrchestratorConfig(
        reconcile_pass=ReconcilePassConfig(enabled=enabled, interval_minutes=interval_minutes)
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    paths.state_file.parent.mkdir(parents=True, exist_ok=True)
    if gh is None:
        gh = FakeGitHub()
        # Wiring tests for _maybe_reconcile_drift expect a clean repo. The
        # default FakeGitHub carries a sample issue/PR that now resolve through
        # the paginated REST snapshots and would produce unrelated drift.
        gh.issues = []
        gh.prs = []
    return OrchestratorApp(tmp_path, paths, config, gh)


def test_loop_forwards_shared_now_to_cadence_gated_lanes(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Issue #828 (critical wiring test): a single frozen ``now`` passed to
    ``loop()`` must reach every cadence-gated lane's ``now`` keyword
    unchanged -- ``_maybe_probe_quota_recovery``, ``_maybe_reconcile_drift``,
    ``_maybe_reclaim_worktrees``, and the module-level
    ``_detect_and_handle_stalled_sessions`` reaper. Each of those functions
    is exercised directly (not via loop()) by its own dedicated test
    elsewhere in this file, so none of those tests would notice a future
    edit that deleted the ``now=now`` forwarding at loop()'s call sites in
    ``_loop_body`` -- this test exists specifically to catch that class of
    regression (L3 "wired", not merely L2 "exists and works standalone").
    Every lane is stubbed to a no-op recorder rather than asserted on
    cadence state, so the test is immune to each lane's own due/not-due
    gating and to the unrelated behavior each lane performs.
    """
    from charlie_work import workflow as workflow_module

    app = _reconcile_pass_app(tmp_path)
    frozen_now = datetime.now(UTC)
    received: dict[str, datetime | None] = {}

    def _record_probe(self: OrchestratorApp, *, now: datetime | None = None) -> None:
        received["probe_quota_recovery"] = now

    def _record_reconcile(self: OrchestratorApp, *, now: datetime | None = None) -> None:
        received["reconcile_drift"] = now

    def _record_reclaim(
        self: OrchestratorApp, *, now: datetime | None = None
    ) -> dict[str, Any] | None:
        received["reclaim_worktrees"] = now
        return None

    def _record_stalled_sessions(
        sessions_dir: Path,
        state_file: Path,
        config: OrchestratorConfig,
        *,
        now: datetime | None = None,
    ) -> list[dict[str, int]]:
        received["stalled_sessions"] = now
        return []

    monkeypatch.setattr(OrchestratorApp, "_maybe_probe_quota_recovery", _record_probe)
    monkeypatch.setattr(OrchestratorApp, "_maybe_reconcile_drift", _record_reconcile)
    monkeypatch.setattr(OrchestratorApp, "_maybe_reclaim_worktrees", _record_reclaim)
    monkeypatch.setattr(
        workflow_module, "_detect_and_handle_stalled_sessions", _record_stalled_sessions
    )

    app.loop(limit=0, now=frozen_now)

    assert received.keys() == {
        "probe_quota_recovery",
        "reconcile_drift",
        "reclaim_worktrees",
        "stalled_sessions",
    }
    for lane, value in received.items():
        assert value is frozen_now, f"{lane} did not receive the pass's frozen now"


def test_maybe_reconcile_drift_noop_when_disabled(tmp_path: Path) -> None:
    """B-AC1/B-AC2: reconcile_pass.enabled=False must skip reconcile entirely --
    no call to reconcile(), no schedule armed, no summary event."""
    app = _reconcile_pass_app(tmp_path, enabled=False)

    def _fail_if_called(*, fix: bool = False) -> CommandResult:
        raise AssertionError("reconcile() must not be called when reconcile_pass is disabled")

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app, "reconcile", _fail_if_called)
    try:
        app._maybe_reconcile_drift()
    finally:
        monkeypatch.undo()

    state = load_state(app.paths.state_file)
    assert state.get("reconcile_pass", {}).get("next_reconcile_at") is None
    events = state.get("events", [])
    assert not [e for e in events if str(e.get("kind", "")).startswith("reconcile_pass")]


def test_maybe_reconcile_drift_runs_and_arms_schedule_when_due(tmp_path: Path) -> None:
    """B-AC1/B-AC2: enabled + due calls _reconcile_locked(fix=True) exactly
    once, arms the next-due schedule ~interval_minutes out, and records a
    single reconcile_pass_completed summary event carrying drift counts.

    Patches ``_reconcile_locked``, not ``reconcile`` (merge-lane-recovery
    D-8a): ``_maybe_reconcile_drift`` calls ``_reconcile_locked`` directly
    because loop()'s caller already holds supervisor.lock for the whole
    pass, and re-entering ``reconcile()`` would re-acquire that same
    non-reentrant lock and always no-op. Patching ``reconcile`` here would
    silently never be invoked and this test would falsely pass with 0 calls
    recorded as a bug, not a confirmation -- see
    test_maybe_reconcile_drift_runs_while_supervisor_lock_held for the test
    that actually exercises that lock-contention distinction end to end."""
    from datetime import UTC, datetime

    app = _reconcile_pass_app(tmp_path, interval_minutes=30)
    original_reconcile_locked = app._reconcile_locked
    calls: list[tuple[bool, bool]] = []

    def _counting_reconcile_locked(
        *,
        fix: bool = False,
        skip_dead_session_sweep: bool = False,
        dry_run: bool = False,
    ) -> CommandResult:
        calls.append((fix, skip_dead_session_sweep))
        return original_reconcile_locked(
            fix=fix,
            skip_dead_session_sweep=skip_dead_session_sweep,
            dry_run=dry_run,
        )

    # frozen_now (issue #828) injected so the schedule assertion below is
    # exact instead of racing _reconcile_locked's own duration (or a CI
    # stall). No downstream real-clock dependency follows in this test, so
    # no offset is needed.
    frozen_now = datetime.now(UTC)
    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app, "_reconcile_locked", _counting_reconcile_locked)
    try:
        app._maybe_reconcile_drift(now=frozen_now)
    finally:
        monkeypatch.undo()

    # merge-lane-recovery §6-B follow-up: the in-loop caller must skip
    # reconcile's own dead-session sweep -- the loop's stall/dead lanes
    # (_detect_and_handle_stalled_sessions /
    # _classify_dead_sessions_and_update_throttle_state) already ran this
    # exact pass, immediately before this call, with grace-period semantics
    # (max_inconclusive_probe_deferrals) that reconcile.py's sweep does not
    # implement.
    assert calls == [(True, True)]

    state = load_state(app.paths.state_file)
    next_at = state["reconcile_pass"]["next_reconcile_at"]
    expected = (
        (frozen_now + timedelta(minutes=30))
        .replace(microsecond=0)
        .isoformat()
        .replace("+00:00", "Z")
    )
    assert next_at == expected

    events = state.get("events", [])
    completed = [e for e in events if e.get("kind") == "reconcile_pass_completed"]
    assert len(completed) == 1
    assert completed[0]["payload"]["drift_detected"] == 0
    assert completed[0]["payload"]["drift_fixed"] == 0
    assert completed[0]["payload"]["drift_remaining"] == 0


def test_maybe_reconcile_drift_waits_until_due(tmp_path: Path) -> None:
    """The periodic cadence must not re-run reconcile before the armed
    next_reconcile_at timestamp."""
    from datetime import UTC, datetime

    from charlie_work.state import arm_reconcile_pass

    app = _reconcile_pass_app(tmp_path, interval_minutes=30)
    not_due = (
        (datetime.now(UTC) + timedelta(minutes=25))
        .replace(microsecond=0)
        .isoformat()
        .replace("+00:00", "Z")
    )
    state = arm_reconcile_pass(load_state(app.paths.state_file), not_due)
    save_state(app.paths.state_file, state)

    def _fail_if_called(*, fix: bool = False) -> CommandResult:
        raise AssertionError("must not reconcile before the scheduled time")

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app, "reconcile", _fail_if_called)
    try:
        app._maybe_reconcile_drift()
    finally:
        monkeypatch.undo()

    state = load_state(app.paths.state_file)
    assert state["reconcile_pass"]["next_reconcile_at"] == not_due
    events = state.get("events", [])
    assert not [e for e in events if str(e.get("kind", "")).startswith("reconcile_pass")]


def test_maybe_reconcile_drift_defers_on_graphql_rate_limit(tmp_path: Path) -> None:
    """B-AC3: reconcile()'s existing GraphQL rate-limit deferral must be
    preserved, not bypassed -- surfaced as a distinguishable
    reconcile_pass_deferred event rather than a silent no-op."""

    class LowBudgetGitHub(FakeGitHub):
        def check_graphql_rate_limit(self, threshold: int) -> tuple[bool, int, int | None]:
            return (False, 50, 1234567890)

    app = _reconcile_pass_app(tmp_path, gh=LowBudgetGitHub())

    app._maybe_reconcile_drift()

    state = load_state(app.paths.state_file)
    assert state["reconcile_pass"]["next_reconcile_at"] is not None
