def test_redispatch_timestamps_pruned_outside_window(tmp_path: Path) -> None:
    """Test that timestamps outside the window are pruned before counting (issue #165)."""
    from datetime import UTC, datetime, timedelta

    config = OrchestratorConfig(
        watchdog=WatchdogConfig(
            enabled=True,
            stall_minutes=20,
            redispatch_window_minutes=240,
            max_auto_redispatch=3,
        ),
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)

    # Setup state with old redispatches outside the window
    state = load_state(paths.state_file)
    now = datetime.now(UTC)
    state["issues"]["123"] = {
        "number": 123,
        "title": "Test issue",
        "url": "https://github.com/test/repo/issues/123",
        "status": "rework_requested",
        "redispatch_at": [
            (now - timedelta(minutes=300)).isoformat().replace("+00:00", "Z"),  # Outside window
            (now - timedelta(minutes=10)).isoformat().replace("+00:00", "Z"),  # Inside window
        ],
    }
    save_state(paths.state_file, state)

    # Test the counting logic directly
    entry = state["issues"]["123"]
    window_start = now - timedelta(minutes=config.watchdog.redispatch_window_minutes)
    prior = [
        t
        for t in entry.get("redispatch_at", [])
        if datetime.fromisoformat(t.replace("Z", "+00:00")) >= window_start
    ]
    redispatch_at = prior + [now.isoformat().replace("+00:00", "Z")]

    # Old timestamp should be pruned, only 2 remain (1 in window + 1 new)
    assert len(redispatch_at) == 2
    assert len(redispatch_at) <= config.watchdog.max_auto_redispatch


def test_redispatch_at_only_written_by_known_call_sites(tmp_path: Path) -> None:
    """Test that redispatch_at is only written by known call sites."""
    # This test verifies by code inspection that redispatch_at is only written in:
    # 1. dispatch_rework normal paths (success + failure + no-op rework pre-dispatch).
    # 2. _classify_dead_sessions_and_update_throttle_state normal paths.
    # 3. _reap_restore_rework_requested (issue #315 review finding 2).
    # Escalated paths now consolidate on _escalate_issue and pass redispatch_at
    # through issue_extra, so direct entry["redispatch_at"] assignments only
    # remain in the non-escalated branches below.

    import charlie_work.workflow as workflow_module
    import inspect

    workflow_source = inspect.getsource(workflow_module)

    # Count direct redispatch_at assignments to entry. After issue #750, the
    # escalated call sites all route through _escalate_issue, so this count
    # only covers non-escalated branches. Any unexpected increase means a new
    # call site is writing redispatch_at.
    redispatch_assignments = workflow_source.count('entry["redispatch_at"]')
    assert redispatch_assignments == 5, (
        f"Expected 5 redispatch_at assignments, found {redispatch_assignments}"
    )


def test_orphaned_worker_detection_with_request_changes_and_unchanged_head(tmp_path: Path) -> None:
    """Regression test for issue #207: dead worker with request_changes and unchanged head should reset to rework_requested."""
    from unittest.mock import patch

    config = OrchestratorConfig(
        devin=DevinConfig(adapter="devin-shell"),
        watchdog=WatchdogConfig(enabled=True, stall_minutes=20),
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)

    # Create initial state with a dispatched issue and dead worker PID
    state = load_state(paths.state_file)
    state["issues"]["207"] = {
        "status": "dispatched",
        "worker_pid": 99999,  # Dead PID
        "worker_process_start_time": 1234567890.0,
        "dispatched_at": "2024-01-01T00:00:00Z",
    }
    state["prs"]["100"] = {
        "decision": "request_changes",
        "reviewed_head_sha": "abc123",
    }
    save_state(paths.state_file, state)

    # Mock GitHub to return an open PR for the issue
    class FakeGitHubForOrphan(FakeGitHub):
        def pr_list(self):
            return [
                {
                    "number": 100,
                    "headRefOid": "abc123",  # Unchanged since request_changes
                    "isCrossRepository": False,
                    "headRepository": {"owner": {"login": "test"}, "name": "repo"},
                    "headRefName": "agent/issue-207",
                }
            ]

    fake_gh = FakeGitHubForOrphan()

    # Mock PID liveness check to return False (dead PID)
    with patch("charlie_work.workflow._worker_pid_alive", return_value=False):
        from charlie_work.workflow import _detect_and_handle_orphaned_workers

        sessions_dir = tmp_path / ".var" / "charlie-work" / "dispatches" / "sessions"
        sessions_dir.mkdir(parents=True, exist_ok=True)

        _detect_and_handle_orphaned_workers(sessions_dir, paths.state_file, config, fake_gh)

    # Load state and verify the transition
    state = load_state(paths.state_file)
    entry = state["issues"]["207"]

    # Status should be reset to rework_requested
    assert entry.get("status") == "rework_requested"
    assert entry.get("dispatched_at") is None

    # Worker PID should be preserved for recovery-path verification (issue #282)
    assert entry["worker_pid"] == 99999
    assert entry["worker_process_start_time"] == 1234567890.0

    # Verify the event was logged
    events = state.get("events", [])
    recovered_events = [e for e in events if e.get("kind") == "orphaned_worker_recovered"]
    assert len(recovered_events) == 1
    assert recovered_events[0]["payload"]["issue_number"] == 207
    assert recovered_events[0]["payload"]["pr_number"] == 100
    assert recovered_events[0]["payload"]["reason"] == "dead_worker_with_request_changes"

    # Issue #773 measurement-first requirement: even the legacy no-terminal-
    # record fallback path now reports pid/exit_code/duration_seconds on the
    # event (exit_code/duration None since no terminal record exists).
    assert recovered_events[0]["payload"]["pid"] == 99999
    assert recovered_events[0]["payload"]["exit_code"] is None
    assert recovered_events[0]["payload"]["duration_seconds"] is None


def test_orphaned_worker_request_changes_recovered_with_watchdog_disabled(
    tmp_path: Path,
) -> None:
    """Issue #1108: the dead-pid orphan recovery sweep must reset a
    ``status=dispatched`` issue with a dead PID and an open PR carrying a
    ``request_changes`` verdict (head unchanged) to ``rework_requested`` even
    when ``watchdog.enabled=False``.

    The ``watchdog.enabled`` flag controls log-mtime stall detection
    (``_detect_stalled_sessions`` / ``_detect_and_handle_stalled_sessions``),
    not the dead-pid state-keyed recovery in
    ``_detect_and_handle_orphaned_workers``. A deployment that disables
    watchdog (e.g. job-cannon, to work around shim log-mtime blindness) must
    not lose the request_changes → rework_requested transition — without it,
    issues with dead workers and open PRs sit wedged in ``dispatched``
    indefinitely with no path to redispatch (the exact 8+ hour stall observed
    2026-08-09/10 on jc #1358, #1479, et al.).
    """
    from unittest.mock import patch

    from charlie_work.workflow import _detect_and_handle_orphaned_workers

    # watchdog disabled — the sweep must still run.
    config = OrchestratorConfig(
        devin=DevinConfig(adapter="devin-shell"),
        watchdog=WatchdogConfig(enabled=False, stall_minutes=20),
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)

    state = load_state(paths.state_file)
    state["issues"]["1108"] = {
        "status": "dispatched",
        "worker_pid": 99999,
        "worker_process_start_time": 1234567890.0,
        "dispatched_at": "2024-01-01T00:00:00Z",
    }
    state["prs"]["100"] = {
        "decision": "request_changes",
        "reviewed_head_sha": "abc123",
    }
    save_state(paths.state_file, state)

    class FakeGitHubForOrphan(FakeGitHub):
        def pr_list(self):
            return [
                {
                    "number": 100,
                    "headRefOid": "abc123",
                    "isCrossRepository": False,
                    "headRepository": {"owner": {"login": "test"}, "name": "repo"},
                    "headRefName": "agent/issue-1108",
                }
            ]

    fake_gh = FakeGitHubForOrphan()

    sessions_dir = tmp_path / ".var" / "charlie-work" / "dispatches" / "sessions"
    sessions_dir.mkdir(parents=True, exist_ok=True)

    with patch("charlie_work.workflow._worker_pid_alive", return_value=False):
        _detect_and_handle_orphaned_workers(sessions_dir, paths.state_file, config, fake_gh)

    state = load_state(paths.state_file)
    entry = state["issues"]["1108"]

    # The sweep fired despite watchdog being disabled: the issue was reset to
    # rework_requested so dispatch_rework can re-select it.
    assert entry.get("status") == "rework_requested"
    assert entry.get("dispatched_at") is None

    events = state.get("events", [])
    recovered_events = [e for e in events if e.get("kind") == "orphaned_worker_recovered"]
    assert len(recovered_events) == 1
    assert recovered_events[0]["payload"]["issue_number"] == 1108
    assert recovered_events[0]["payload"]["pr_number"] == 100
    assert recovered_events[0]["payload"]["reason"] == "dead_worker_with_request_changes"


