def test_cross_family_request_changes_verdict_persists_required_changes(
    tmp_path: Path,
) -> None:
    """End-to-end: a cross-family report's parsed request_changes verdict,
    recorded the same way ``_record_cross_family_verdicts`` does (workflow.py),
    ends up with a populated ``required_changes`` in review-decision.json --
    the exact defect this fix closes (8 of 20 request_changes verdicts had it
    silently empty)."""
    body = (
        "**MAJOR**\nfile.py:10 does the wrong thing\n\n"
        "Verdict: MAJOR issue blocks merge\n\n"
        "```json\n"
        '{"decision": "request_changes", '
        '"summary": "file.py:10 has a real bug that breaks X", '
        '"required_changes": ["Fix the off-by-one in file.py:10", '
        '"Add a regression test for the empty-list case"]}\n'
        "```\n"
    )
    report_text = f"# Cross-family adversarial review — `glm-5.2`\n\n{_CAVEAT}\n\n---\n\n{body}\n"
    parsed = parse_cross_family_verdict(report_text)
    assert parsed is not None
    assert parsed.decision == "request_changes"

    config = OrchestratorConfig()
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    # Mirrors workflow.py's _record_cross_family_verdicts call site exactly.
    # PR 456 is FakeGitHub's seeded default PR.
    result = app.record_review(
        456,
        parsed.decision,
        summary=parsed.summary,
        required_changes=parsed.required_changes,
    )
    assert result.ok

    decision = json.loads(
        (paths.prs / "pr-456" / "review-decision.json").read_text(encoding="utf-8")
    )
    assert decision["required_changes"] == [
        "Fix the off-by-one in file.py:10",
        "Add a regression test for the empty-list case",
    ]
    assert decision["summary"] == "file.py:10 has a real bug that breaks X"


def test_cross_family_legacy_path_verdict_with_empty_required_changes_gets_derived(
    tmp_path: Path,
) -> None:
    """AC-6 (cross-family producer): the legacy Markdown-only parse path
    (no JSON verdict block) never itemizes required_changes -- it only ever
    extracts a summary -- so a request_changes verdict recorded from it
    always arrives at record_review with required_changes=() and a real,
    non-vacuous summary. This is the shape record_review's derivation
    exists for. Contrast with test_handle_malformed_cross_family_verdict_*:
    a JSON verdict block declaring request_changes with an empty
    required_changes is diverted to MalformedCrossFamilyVerdict before ever
    reaching record_review (issue #795) -- this test's report has no JSON
    block at all, so that defense-in-depth layer does not apply here and
    record_review's own derivation is what prevents the content-free
    outcome."""
    body = "**MAJOR**\nreal bug\n\nVerdict: MAJOR issues block merge"
    report_text = f"# Cross-family adversarial review — `glm-5.2`\n\n{_CAVEAT}\n\n---\n\n{body}\n"
    parsed = parse_cross_family_verdict(report_text)
    assert isinstance(parsed, CrossFamilyVerdict)
    assert parsed.decision == "request_changes"
    assert parsed.required_changes == ()
    assert parsed.summary and not _summary_is_vacuous(parsed.summary)

    config = OrchestratorConfig()
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    # Mirrors workflow.py's _record_cross_family_verdicts call site exactly.
    result = app.record_review(
        456,
        parsed.decision,
        summary=parsed.summary,
        required_changes=parsed.required_changes,
    )
    assert result.ok is True

    decision = json.loads(
        (paths.prs / "pr-456" / "review-decision.json").read_text(encoding="utf-8")
    )
    assert decision["required_changes"] == [parsed.summary]
    assert decision["findings_channel"] == "derived"


def test_rework_brief_contains_required_changes_from_verdict(tmp_path: Path) -> None:
    """Issue #632 defect 1: a request_changes verdict's required_changes must
    reach the rework brief. The brief reads review-decision.json itself (single
    point of enforcement), so asserting on the rendered content — not on the
    call having happened — is the right check."""
    config = OrchestratorConfig()
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    findings = ["add null check in parse()", "update tests for edge case"]
    app.record_review(
        456,
        "request_changes",
        summary="fix A",
        required_changes=findings,
    )

    brief = (paths.prs / "pr-456" / "rework-prompt.md").read_text(encoding="utf-8")
    for finding in findings:
        assert finding in brief, f"finding missing from brief: {finding!r}"
    # The prose summary rides in the dispatch-note slot and must still appear.
    assert "fix A" in brief
    # The section header is present so the worker can locate the list.
    assert "## Required changes" in brief


def test_rework_brief_keeps_both_dispatch_note_and_findings(tmp_path: Path) -> None:
    """Issue #632 defect 2: the no-op-churn / merge-conflict routing path
    passes an operational note into the brief. That note must accompany the
    findings instead of displacing them — the #510 regression shipped a brief
    with the churn message and zero findings."""
    config = OrchestratorConfig()
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    pr_dir = paths.prs / "pr-456"
    pr_dir.mkdir(parents=True, exist_ok=True)
    # A pre-existing verdict with structured findings on disk.
    (pr_dir / "review-decision.json").write_text(
        json.dumps(
            {
                "decision": "request_changes",
                "summary": "round-1 summary",
                "required_changes": ["fix the off-by-one", "add a regression test"],
            }
        ),
        encoding="utf-8",
    )
    pr = {
        "number": 456,
        "title": "Fix #123: search",
        "url": "https://example.test/pull/456",
        "headRefName": "agent/issue-123-fix-search",
    }
    operational_note = (
        "The previous rework cycle produced no actual content change. Push the real fix."
    )
    app._write_rework_prompt(pr, 123, operational_note)

    brief = (pr_dir / "rework-prompt.md").read_text(encoding="utf-8")
    # The operational note is preserved...
    assert "no actual content change" in brief
    # ...and the findings are still present alongside it.
    assert "fix the off-by-one" in brief
    assert "add a regression test" in brief
    # The sidecar note is written for dispatch-time regeneration.
    assert (pr_dir / "rework-dispatch-note.txt").read_text(encoding="utf-8") == operational_note


def test_dispatch_rework_regenerates_stale_brief_after_decision_edit(
    tmp_path: Path,
) -> None:
    """Issue #632 defect 4 / #510 case: dispatch_rework reads the brief
    verbatim, so a hand-corrected review-decision.json never reached the
    worker. The brief must be regenerated when the verdict is newer than the
    brief, reflecting the edit."""
    config = OrchestratorConfig(
        devin=DevinConfig(
            adapter="command",
            dispatch_command=(
                sys.executable,
                "-c",
                "import sys; print(sys.argv[1])",
                "{issue_number}",
            ),
        )
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)

    class ReworkGitHub(FakeGitHub):
        def __init__(self) -> None:
            super().__init__()
            self.issues[0]["labels"] = [{"name": "agent:needs-rework"}]

    paths.root.mkdir(parents=True, exist_ok=True)
    with state_lock(paths.state_file):
        state = load_state(paths.state_file)
        state["issues"]["123"] = {
            "number": 123,
            "title": "Fix search",
            "url": "https://example.test/issues/123",
            "status": "rework_requested",
        }
        save_state(paths.state_file, state)

    app = OrchestratorApp(tmp_path, paths, config, ReworkGitHub())

    pr_dir = tmp_path / ".var" / "charlie-work" / "prs" / "pr-456"
    pr_dir.mkdir(parents=True)
    # A stale brief predating the fix: churn note, zero findings — exactly
    # the #510 artifact.
    brief_path = pr_dir / "rework-prompt.md"
    brief_path.write_text("# Rework\n\nThe previous cycle was a no-op.\n", encoding="utf-8")
    # The operator then corrects the verdict by hand, adding the findings.
    decision_path = pr_dir / "review-decision.json"
    decision_path.write_text(
        json.dumps(
            {
                "decision": "request_changes",
                "summary": "corrected verdict",
                "required_changes": ["handle the empty-list case", "guard the index access"],
            }
        ),
        encoding="utf-8",
    )
    # Make the corrected verdict strictly newer than the stale brief.
    now = time.time()
    os.utime(brief_path, (now, now))
    os.utime(decision_path, (now + 10, now + 10))

    result = app.dispatch_rework()

    assert result.ok is True, result.message
    assert result.data["selected_count"] == 1
    regenerated = brief_path.read_text(encoding="utf-8")
    # The regenerated brief reflects the edited verdict.
    assert "handle the empty-list case" in regenerated
    assert "guard the index access" in regenerated
    # The stale churn-only content is gone.
    assert "The previous cycle was a no-op." not in regenerated


def test_dispatch_rework_regenerates_brief_after_renderer_change(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Issue #800: the brief goes stale along a second axis the mtime gate
    cannot see.

    ``_is_verdict_newer_than_brief`` compares timestamps, so it only detects
    *decision content* drift. The #800 case is the other axis: the decision is
    byte-identical and older than the brief, but the **renderer** changed
    underneath it (commit ``35c072d`` added tier-2/tier-3 fallbacks to
    ``_render_required_changes_section``; #883 changed ``rework.md`` itself).
    Every brief already on disk then keeps rendering through the old code
    forever, because nothing ever makes the verdict look newer.

    Monkeypatching the renderer reproduces that exactly: same decision, same
    mtimes, different output. The brief must pick the change up at dispatch.
    """
    from charlie_work import workflow as workflow_module
    from charlie_work.workflow import _is_verdict_newer_than_brief

    config = OrchestratorConfig(
        devin=DevinConfig(
            adapter="command",
            dispatch_command=(
                sys.executable,
                "-c",
                "import sys; print(sys.argv[1])",
                "{issue_number}",
            ),
        )
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)

    class ReworkGitHub(FakeGitHub):
        def __init__(self) -> None:
            super().__init__()
            self.issues[0]["labels"] = [{"name": "agent:needs-rework"}]

    paths.root.mkdir(parents=True, exist_ok=True)
    with state_lock(paths.state_file):
        state = load_state(paths.state_file)
        state["issues"]["123"] = {
            "number": 123,
            "title": "Fix search",
            "url": "https://example.test/issues/123",
            "status": "rework_requested",
        }
        save_state(paths.state_file, state)

    gh = ReworkGitHub()
    app = OrchestratorApp(tmp_path, paths, config, gh)

    pr_dir = tmp_path / ".var" / "charlie-work" / "prs" / "pr-456"
    pr_dir.mkdir(parents=True)
    decision_path = pr_dir / "review-decision.json"
    decision_path.write_text(
        json.dumps(
            {
                "decision": "request_changes",
                "summary": "needs work",
                "required_changes": ["handle the empty-list case"],
            }
        ),
        encoding="utf-8",
    )
    # Write the brief through the real writer, so it carries a dispatch-note
    # sidecar exactly as production briefs do. Seed it from the *same* PR dict
    # dispatch_rework will re-render with, so the renderer swap below is the
    # only thing that differs — otherwise a PR-metadata mismatch would
    # regenerate the brief and the test would pass without proving anything.
    pr = gh.prs[0]
    brief_path = app._write_rework_prompt(pr, 123, "the operational note")
    original = brief_path.read_text(encoding="utf-8")
    assert "handle the empty-list case" in original

    # The decision is *older* than the brief, so the #632 mtime gate is
    # definitively off — this test cannot pass through that path.
    now = time.time()
    os.utime(decision_path, (now, now))
    os.utime(brief_path, (now + 10, now + 10))
    assert not _is_verdict_newer_than_brief(decision_path, brief_path)

    # Now the renderer changes, with the decision untouched.
    monkeypatch.setattr(
        workflow_module,
        "_render_required_changes_section",
        lambda decision: "## Required changes\n\nRENDERED-BY-NEW-CODE\n",
    )

    result = app.dispatch_rework()

    assert result.ok is True, result.message
    assert result.data["selected_count"] == 1
    regenerated = brief_path.read_text(encoding="utf-8")
    assert "RENDERED-BY-NEW-CODE" in regenerated
    # The note survives the regeneration: it is replayed from the sidecar,
    # which is what makes re-rendering input-preserving rather than lossy.
    assert "the operational note" in regenerated
    # A silent rewrite would be unauditable, and the two staleness axes are
    # worth telling apart in the log: this one is renderer drift, not the
    # #632 newer-verdict case.
    events = query_events(paths.state_file, kind="rework_brief_regenerated")
    assert len(events) == 1, events
    assert events[0]["payload"]["reason"] == "renderer_drift"
    assert events[0]["payload"]["pr_number"] == 456


def test_dispatch_rework_leaves_brief_untouched_when_nothing_changed(
    tmp_path: Path,
) -> None:
    """Complement to the #800 regeneration test: re-rendering is unconditional,
    but *writing* is not.

    Without this the fix would rewrite every brief on every dispatch pass,
    churning mtimes that ``_is_verdict_newer_than_brief`` reads. Content is
    compared before writing, so a brief that is already current keeps its
    bytes and its mtime.
    """
    config = OrchestratorConfig(
        devin=DevinConfig(
            adapter="command",
            dispatch_command=(
                sys.executable,
                "-c",
                "import sys; print(sys.argv[1])",
                "{issue_number}",
            ),
        )
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)

    class ReworkGitHub(FakeGitHub):
        def __init__(self) -> None:
            super().__init__()
            self.issues[0]["labels"] = [{"name": "agent:needs-rework"}]

    paths.root.mkdir(parents=True, exist_ok=True)
    with state_lock(paths.state_file):
        state = load_state(paths.state_file)
        state["issues"]["123"] = {
            "number": 123,
            "title": "Fix search",
            "url": "https://example.test/issues/123",
            "status": "rework_requested",
        }
        save_state(paths.state_file, state)

    gh = ReworkGitHub()
    app = OrchestratorApp(tmp_path, paths, config, gh)

    pr_dir = tmp_path / ".var" / "charlie-work" / "prs" / "pr-456"
    pr_dir.mkdir(parents=True)
    (pr_dir / "review-decision.json").write_text(
        json.dumps(
            {
                "decision": "request_changes",
                "summary": "needs work",
                "required_changes": ["handle the empty-list case"],
            }
        ),
        encoding="utf-8",
    )
    pr = gh.prs[0]
    brief_path = app._write_rework_prompt(pr, 123, "the operational note")
    before = brief_path.read_text(encoding="utf-8")
    before_mtime = brief_path.stat().st_mtime_ns

    result = app.dispatch_rework()

    assert result.ok is True, result.message
    assert brief_path.read_text(encoding="utf-8") == before
    assert brief_path.stat().st_mtime_ns == before_mtime


def test_dispatch_rework_does_not_regenerate_when_sidecar_is_unreadable(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Re-rendering is only safe because the dispatch note can be replayed from
    the sidecar. An unreadable sidecar must be treated exactly like an absent
    one — fall back to the mtime gate — because regenerating with an empty note
    would silently drop the note the brief is carrying.

    Its positive control is ``..._regenerates_brief_after_renderer_change``:
    identical setup and identical mtime ordering, differing only in that the
    sidecar is readable there. That one regenerates and this one must not, so
    "no regeneration" here is attributable to the sidecar rather than to the
    PR never being selected for dispatch at all.
    """
    from charlie_work import workflow as workflow_module

    config = OrchestratorConfig(
        devin=DevinConfig(
            adapter="command",
            dispatch_command=(
                sys.executable,
                "-c",
                "import sys; print(sys.argv[1])",
                "{issue_number}",
            ),
        )
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)

    class ReworkGitHub(FakeGitHub):
        def __init__(self) -> None:
            super().__init__()
            self.issues[0]["labels"] = [{"name": "agent:needs-rework"}]

    paths.root.mkdir(parents=True, exist_ok=True)
    with state_lock(paths.state_file):
        state = load_state(paths.state_file)
        state["issues"]["123"] = {
            "number": 123,
            "title": "Fix search",
            "url": "https://example.test/issues/123",
            "status": "rework_requested",
        }
        save_state(paths.state_file, state)

    gh = ReworkGitHub()
    app = OrchestratorApp(tmp_path, paths, config, gh)

    pr_dir = tmp_path / ".var" / "charlie-work" / "prs" / "pr-456"
    pr_dir.mkdir(parents=True)
    decision_path = pr_dir / "review-decision.json"
    decision_path.write_text(
        json.dumps(
            {
                "decision": "request_changes",
                "summary": "needs work",
                "required_changes": ["handle the empty-list case"],
            }
        ),
        encoding="utf-8",
    )
    pr = gh.prs[0]
    brief_path = app._write_rework_prompt(pr, 123, "the operational note")
    # Corrupt the sidecar: not valid UTF-8, so reading it raises.
    (pr_dir / "rework-dispatch-note.txt").write_bytes(b"\xff\xfe not utf-8 \xff")
    before = brief_path.read_text(encoding="utf-8")

    now = time.time()
    os.utime(decision_path, (now, now))
    os.utime(brief_path, (now + 10, now + 10))

    monkeypatch.setattr(
        workflow_module,
        "_render_required_changes_section",
        lambda decision: "## Required changes\n\nRENDERED-BY-NEW-CODE\n",
    )

    result = app.dispatch_rework()

    assert result.ok is True, result.message
    # The renderer changed, but without a replayable note the brief is left
    # alone rather than rewritten without its note.
    assert brief_path.read_text(encoding="utf-8") == before
    assert "the operational note" in before


def test_rework_brief_omits_required_changes_for_approved_verdict(tmp_path: Path) -> None:
    """Issue #632 edge case: an approved verdict may carry a non-empty
    required_changes list (the field is optional for every decision). The
    merge-conflict / no-CI / cross-pr-revert routes render a rework brief
    for an already-approved PR whose dispatch note explicitly says "do not
    re-litigate the review". Rendering a "Required changes ... before this
    PR can be approved" section into that brief would be contradictory.
    The section must only appear for a request_changes verdict."""
    config = OrchestratorConfig()
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    pr_dir = paths.prs / "pr-456"
    pr_dir.mkdir(parents=True, exist_ok=True)
    # An approved verdict that nonetheless carries required_changes (a
    # reviewer mistake, or stale carry-forward from a prior round).
    (pr_dir / "review-decision.json").write_text(
        json.dumps(
            {
                "decision": "approved",
                "summary": "lgtm",
                "required_changes": ["add a docstring", "rename foo to bar"],
            }
        ),
        encoding="utf-8",
    )
    pr = {
        "number": 456,
        "title": "Fix #123: search",
        "url": "https://example.test/pull/456",
        "headRefName": "agent/issue-123-fix-search",
    }
    # The merge-conflict operational note says "do not re-litigate".
    operational_note = (
        "The PR branch has a merge conflict. Merge the base branch and resolve. "
        "The code changes are already approved; do not re-litigate the review."
    )
    app._write_rework_prompt(pr, 123, operational_note)

    brief = (pr_dir / "rework-prompt.md").read_text(encoding="utf-8")
    # The operational note is present.
    assert "do not re-litigate" in brief
    assert "merge conflict" in brief
    # The contradictory required-changes section is NOT rendered.
    assert "## Required changes" not in brief
    assert "before this PR can be approved" not in brief
    assert "add a docstring" not in brief
    assert "rename foo to bar" not in brief


def test_rework_brief_falls_back_to_summary_when_required_changes_empty(
    tmp_path: Path,
) -> None:
    """Bug reproducer (F1): measured across the on-disk corpus, request_changes
    verdicts with a populated required_changes are 0 of 20 -- prompts/review.md
    historically documented the field as optional, so reviewers reliably fill
    in `summary` and skip `required_changes`. Before F1,
    _render_required_changes_section returned "" whenever required_changes
    was empty, so the worker's rework brief contained none of that summary
    content even though it was real, substantive review findings sitting
    right there in review-decision.json. Must fail before F1, pass after.

    The reviewer_summary text here is the real PR #766 reproduction string
    from issue #781 -- it contains a live closing keyword ("does not fix
    #649") that must reach the brief DEFANGED (issue #781 outbound fix), so
    this test also doubles as an AC4-adjacent regression guard: the summary
    fallback tier must not leak `fix #649` verbatim into a worker's brief."""
    config = OrchestratorConfig()
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    reviewer_summary = (
        "BLOCKER - does not fix #649. The pin is a no-op over uv's resolver; "
        "the underlying version conflict is still unresolved."
    )
    app.record_review(
        456,
        "request_changes",
        summary=reviewer_summary,
        required_changes=[],
    )

    brief = (paths.prs / "pr-456" / "rework-prompt.md").read_text(encoding="utf-8")
    assert "## Required changes" in brief
    # Content (the reviewer's findings) survives, defanged of the live
    # closing-keyword syntax that would otherwise let GitHub or a worker's
    # own PR body auto-close/mis-bind issue #649.
    assert "does not fix issue 649" in brief, "reviewer summary missing from brief"
    assert "does not fix #649" not in brief, "live closing keyword leaked into brief"


def test_render_required_changes_section_populated_list_unaffected_by_fallback() -> None:
    """Non-regression: when required_changes IS populated, the enumerated
    list renders exactly as before even though a summary is also present --
    the summary-fallback and escape-hatch tiers must never fire when there is
    real structured content to show."""
    decision = {
        "decision": "request_changes",
        "summary": "This summary must not appear in the rendered section.",
        "required_changes": ["fix the off-by-one", "add a regression test"],
    }

    section = _render_required_changes_section(decision)

    assert "## Required changes" in section
    assert "- fix the off-by-one" in section
    assert "- add a regression test" in section
    # The fallback/escape-hatch framing must not leak in alongside the list.
    assert "did not record a structured findings list" not in section
    assert "REVIEWER FINDINGS UNAVAILABLE" not in section
    assert "This summary must not appear" not in section


def test_render_required_changes_section_both_empty_renders_escape_hatch() -> None:
    """Hard requirement (F1): when both required_changes and summary are
    empty on a request_changes verdict, the section must never look like
    "nothing to change" -- it must loudly say the findings are unavailable
    and point the worker at the PR's review comments on GitHub instead of
    silently rendering an empty section."""
    decision = {"decision": "request_changes", "summary": "", "required_changes": []}

    section = _render_required_changes_section(decision)

    assert section.strip() != ""
    assert "REVIEWER FINDINGS UNAVAILABLE" in section
    assert "is NOT a signal that there is nothing to change" in section
    assert "GitHub" in section


def test_render_required_changes_section_blocked_both_empty_renders_escape_hatch() -> None:
    """Defensive extension of the same hard requirement to `blocked`: the
    decision-agnostic janitor-gate rework routes (merge-conflict / no-op
    repair) can carry forward whatever verdict was last on disk, including a
    `blocked` one. Suppressing the enumerated list / summary fallback for
    `blocked` (see the omits-for-approved-style suppression covered above)
    is deliberate, but suppressing it AND leaving the worker with zero signal
    that something was withheld is not -- the both-empty escape hatch still
    fires."""
    decision = {"decision": "blocked", "summary": "", "required_changes": []}

    section = _render_required_changes_section(decision)

    assert "REVIEWER FINDINGS UNAVAILABLE" in section


# --------------------------------------------------------------------------
# Issue #792: verdicts recorded by the current record_review carry an
# explicit findings_channel marker ("vacuous" or "derived"). These tests
# cover the renderer's handling of that marker directly, independent of the
# shape-based (required_changes/summary) tiers above, which exist only to
# infer the same distinction for pre-#792 records with no marker at all.
# --------------------------------------------------------------------------


def test_render_required_changes_section_vacuous_marker_renders_escape_hatch() -> None:
    """A findings_channel="vacuous" verdict always renders tier 3, even
    though `summary` is technically non-blank (it may carry the historical
    placeholder) -- rendering it as real content (tier 2) would silently
    present content-free text as the reviewer's actual findings."""
    decision = {
        "decision": "request_changes",
        "summary": LEGACY_VACUOUS_SUMMARY,
        "required_changes": [],
        "findings_channel": "vacuous",
    }

    section = _render_required_changes_section(decision)

    assert "REVIEWER FINDINGS UNAVAILABLE" in section
    assert LEGACY_VACUOUS_SUMMARY not in section


def test_render_required_changes_section_vacuous_marker_fires_for_blocked_too() -> None:
    """The vacuous marker's escape hatch is decision-agnostic -- it fires for
    `blocked` exactly as it does for `request_changes`, unlike the "derived"
    marker below which is request_changes-specific."""
    decision = {
        "decision": "blocked",
        "summary": LEGACY_VACUOUS_SUMMARY,
        "required_changes": [],
        "findings_channel": "vacuous",
    }

    section = _render_required_changes_section(decision)

    assert "REVIEWER FINDINGS UNAVAILABLE" in section


def test_render_required_changes_section_derived_marker_renders_summary_verbatim() -> None:
    """A findings_channel="derived" request_changes verdict renders the
    tier-2-shaped verbatim-summary section even though required_changes is
    now populated (record_review copied summary into it) -- it must not
    fall into tier 1's bullet-list rendering, which would wrap an entire
    multi-sentence summary as a single bullet."""
    prose = "The retry wrapper swallows the exception type; callers cannot distinguish causes."
    decision = {
        "decision": "request_changes",
        "summary": prose,
        "required_changes": [prose],
        "findings_channel": "derived",
    }

    section = _render_required_changes_section(decision)

    assert prose in section
    assert f"- {prose}" not in section
    assert "did not record a structured findings list" in section


def test_render_required_changes_section_derived_marker_suppressed_for_blocked() -> None:
    """Unlike "vacuous", the "derived" marker's special-cased rendering only
    applies to request_changes (see the docstring's blocked-suppression
    rule) -- for `blocked` it falls through to the pre-existing shape-based
    tiers, where a populated required_changes on a blocked verdict is
    suppressed by design (blocked's "what must change before approval"
    framing doesn't fit blocked's routes)."""
    prose = "Security review flagged an unauthenticated endpoint."
    decision = {
        "decision": "blocked",
        "summary": prose,
        "required_changes": [prose],
        "findings_channel": "derived",
    }

    section = _render_required_changes_section(decision)

    assert section == ""


def test_defang_closing_keywords_strips_live_keyword_but_keeps_number_legible() -> None:
    # Issue #781 AC3: defang_closing_keywords rewrites `<keyword> #N` to
    # `<keyword> issue N` -- the rewritten text no longer matches the
    # closing-keyword regex (so it can no longer auto-close or falsely bind
    # via linked_issue_number), but the issue number stays legible to a
    # human reader.
    from charlie_work.github import _CLOSING_KEYWORD_REF, defang_closing_keywords

    text = "does not fix #649"
    defanged = defang_closing_keywords(text)

    assert _CLOSING_KEYWORD_REF.search(defanged) is None
    assert "649" in defanged, "issue number must remain legible to a human"
    assert defanged == "does not fix issue 649"


def test_defang_closing_keywords_preserves_non_keyword_hash_refs() -> None:
    # Bare `#N` (no preceding closing keyword) and `issue #N` mentions pass
    # through untouched -- defang targets only the live auto-close syntax.
    # Multiple keyword refs in one string are each independently defanged.
    from charlie_work.github import defang_closing_keywords

    assert defang_closing_keywords("see #5 for context") == "see #5 for context"
    assert defang_closing_keywords("related to issue #5") == "related to issue #5"
    assert (
        defang_closing_keywords("Closes #1 and also fixes #2")
        == "Closes issue 1 and also fixes issue 2"
    )


def test_render_required_changes_section_defangs_live_keyword_in_list_tier() -> None:
    # Issue #781 AC4: reviewer prose in the required_changes list tier must
    # not carry a live closing keyword into the rendered brief -- a worker
    # reads this brief and writes its own PR body from it, a boundary
    # linked_issue_number's hijack-safety check never sees.
    from charlie_work.github import _CLOSING_KEYWORD_REF

    decision = {
        "decision": "request_changes",
        "summary": "",
        "required_changes": ["this does not fix #649, dig deeper"],
    }

    section = _render_required_changes_section(decision)

    assert "does not fix issue 649" in section
    assert _CLOSING_KEYWORD_REF.search(section) is None, "live keyword survived"


def test_render_required_changes_section_defangs_live_keyword_in_summary_tier() -> None:
    # Same guarantee for the summary-fallback tier (tier 2).
    from charlie_work.github import _CLOSING_KEYWORD_REF

    decision = {
        "decision": "request_changes",
        "summary": "BLOCKER - does not fix #649. Still broken.",
        "required_changes": [],
    }

    section = _render_required_changes_section(decision)

    assert "does not fix issue 649" in section
    assert _CLOSING_KEYWORD_REF.search(section) is None, "live keyword survived"


def test_no_op_rework_repair_brief_preserves_reviewer_summary(tmp_path: Path) -> None:
    """F3: _request_no_op_rework_repair's hardcoded no-op note must not
    displace the reviewer's findings. It routes through _route_to_rework,
    which calls the shared _write_rework_prompt -- the same single point of
    enforcement (issue #632) every other rework route uses -- so the
    reviewer's on-disk verdict is read fresh from review-decision.json,
    independent of the `summary` argument this method builds. Verified
    concretely here rather than assumed: this test fails if that separation
    is ever broken (e.g. a future edit threads the no-op text into
    review-decision.json's own `summary`, or bypasses _write_rework_prompt)."""
    config = OrchestratorConfig()
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    pr_dir = paths.prs / "pr-456"
    pr_dir.mkdir(parents=True, exist_ok=True)
    reviewer_summary = (
        "BLOCKER - does not fix #649. The pin is a no-op over uv's resolver; "
        "the underlying version conflict is still unresolved."
    )
    decision = {
        "decision": "request_changes",
        "summary": reviewer_summary,
        "required_changes": [],
    }
    (pr_dir / "review-decision.json").write_text(json.dumps(decision), encoding="utf-8")
    pr = fake_gh.pr_view(456)

    result = app._request_no_op_rework_repair(pr, 123, decision)

    assert result is None, f"expected a clean label transition, got {result!r}"
    brief = (pr_dir / "rework-prompt.md").read_text(encoding="utf-8")
    # The no-op operational note (the "dispatch_note") is present...
    assert "no actual content change" in brief
    # ...and the reviewer's original findings are still present alongside it,
    # not replaced by it -- defanged of the live closing keyword (issue
    # #781 outbound fix) the same way as the summary-fallback test above.
    assert "does not fix issue 649" in brief
    assert "does not fix #649" not in brief, "live closing keyword leaked into brief"


def test_no_op_rework_repair_note_survives_dispatch_rework_regeneration(tmp_path: Path) -> None:
    """Issue #887: the operational note from _route_to_rework must survive
    a dispatch_rework re-render unchanged.

    _request_no_op_rework_repair routes through _route_to_rework, which uses
    the shared _write_rework_prompt. That writer also writes the
    rework-dispatch-note.txt sidecar. dispatch_rework re-renders stale briefs
    and replays the note from the sidecar; this test extends the same no-op
    repair setup through a full dispatch_rework call and a newer-verdict
    re-render, asserting the operational note is still present in the
    regenerated brief. A future writer that bypasses _write_rework_prompt and
    leaves the sidecar absent or stale would fail this test, because the
    re-render would either drop the note (mtime-gate empty note) or replay a
    stale one."""
    config = OrchestratorConfig(
        devin=DevinConfig(
            adapter="command",
            dispatch_command=(
                sys.executable,
                "-c",
                "import sys; print(sys.argv[1])",
                "{issue_number}",
            ),
        )
    )
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    paths.root.mkdir(parents=True, exist_ok=True)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    pr_dir = paths.prs / "pr-456"
    pr_dir.mkdir(parents=True, exist_ok=True)
    reviewer_summary = (
        "BLOCKER - does not fix #649. The pin is a no-op over uv's resolver; "
        "the underlying version conflict is still unresolved."
    )
    decision = {
        "decision": "request_changes",
        "summary": reviewer_summary,
        "required_changes": [],
    }
    (pr_dir / "review-decision.json").write_text(json.dumps(decision), encoding="utf-8")
    pr = fake_gh.pr_view(456)

    result = app._request_no_op_rework_repair(pr, 123, decision)
    assert result is None, f"expected a clean label transition, got {result!r}"

    brief_path = pr_dir / "rework-prompt.md"
    note_path = pr_dir / "rework-dispatch-note.txt"
    before = brief_path.read_text(encoding="utf-8")
    # The no-op operational note (the "dispatch_note") is present...
    assert "no actual content change" in before
    # ...and the reviewer's original findings are present alongside it.
    assert "does not fix issue 649" in before
    # _write_rework_prompt produced a sidecar for dispatch-time re-render.
    operational_note = (
        "The previous rework cycle produced no actual content change (the diff or head "
        "matches the last request_changes verdict). Check the branch worktree for "
        "unpushed commits and push the real fix, or explain in the PR body why no "
        "further change was needed."
    )
    assert note_path.read_text(encoding="utf-8") == operational_note

    # The operator / reviewer updates the verdict with a new finding and makes
    # it newer than the brief. This is the #632 axis that forces a re-render.
    (pr_dir / "review-decision.json").write_text(
        json.dumps(
            {
                "decision": "request_changes",
                "summary": reviewer_summary,
                "required_changes": ["add a regression test for the empty-list case"],
            }
        ),
        encoding="utf-8",
    )
    now = time.time()
    os.utime(brief_path, (now, now))
    os.utime(note_path, (now, now))
    os.utime(pr_dir / "review-decision.json", (now + 10, now + 10))

    result = app.dispatch_rework()

    assert result.ok is True, result.message
    assert result.data["selected_count"] == 1
    after = brief_path.read_text(encoding="utf-8")
    # The regenerated brief picked up the new verdict finding.
    assert "add a regression test for the empty-list case" in after
    # The operational note from _route_to_rework was replayed from the sidecar
    # and survived the re-render.
    assert "no actual content change" in after
    # The sidecar itself is unchanged.
    assert note_path.read_text(encoding="utf-8") == operational_note
    # The regeneration is recorded with the correct axis.
    events = query_events(paths.state_file, kind="rework_brief_regenerated")
    assert len(events) == 1, events
    assert events[0]["payload"]["reason"] == "verdict_newer"
    assert events[0]["payload"]["pr_number"] == 456


def _normalize_ws(text: str) -> str:
    """Collapse whitespace (including the template's hard line-wraps) so
    substring assertions don't depend on exact word-wrap columns."""
    return " ".join(text.split())


def test_rework_brief_orders_findings_before_demoted_base_merge_bullet(
    tmp_path: Path,
) -> None:
    """F4 (docs/plans/rework-findings-channel.md, #6): the base-merge bullet
    used to be the unconditional, first bullet of `## Required behavior`. When
    a verdict rendered zero findings, that made "merge the base branch" the
    only concrete instruction in the brief -- workers complied, the head
    advanced by a merge commit only, and the janitor correctly flagged the
    result a no-op. The findings-action bullet must now open the section, and
    the base-merge bullet must be demoted (present, but neither first nor
    unconditional)."""
    config = OrchestratorConfig()
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    pr_dir = paths.prs / "pr-456"
    pr_dir.mkdir(parents=True, exist_ok=True)
    (pr_dir / "review-decision.json").write_text(
        json.dumps(
            {
                "decision": "request_changes",
                "summary": "round-1 summary",
                "required_changes": ["fix the off-by-one", "add a regression test"],
            }
        ),
        encoding="utf-8",
    )
    pr = {
        "number": 456,
        "title": "Fix #123: search",
        "url": "https://example.test/pull/456",
        "headRefName": "agent/issue-123-fix-search",
    }
    app._write_rework_prompt(pr, 123, "")

    brief = (pr_dir / "rework-prompt.md").read_text(encoding="utf-8")
    # The findings render well above `## Required behavior` at all.
    assert brief.index("fix the off-by-one") < brief.index("## Required behavior")

    behavior = brief.split("## Required behavior", 1)[1].split("\n## ", 1)[0]
    bullets = [_normalize_ws(b) for b in behavior.split("\n- ") if b.strip()]
    findings_bullet_idx = next(i for i, b in enumerate(bullets) if "the review above" in b)
    merge_bullet_idx = next(i for i, b in enumerate(bullets) if "merge the PR's base branch" in b)

    # The findings-action bullet opens the section; the base-merge bullet
    # comes strictly later -- reordered, not just co-present.
    assert findings_bullet_idx == 0
    assert findings_bullet_idx < merge_bullet_idx

    norm_behavior = _normalize_ws(behavior)
    # Demoted to a self-conditional trigger, not the mandated opening action.
    assert "If your branch is behind its base or the PR shows a merge conflict" in norm_behavior
    assert "First, merge the PR's base branch" not in norm_behavior


def test_rework_brief_omits_unconditional_address_findings_sentence_without_findings(
    tmp_path: Path,
) -> None:
    """F4: the brief used to assert 'Address every Critical and Important
    finding directly' unconditionally, instructing the worker to act on an
    empty set whenever the verdict rendered zero findings. That sentence must
    never render, in favor of self-conditional wording that references "the
    findings above" without asserting they exist. Uses an approved verdict
    (not request_changes with an empty required_changes list) so this keeps
    exercising the empty-findings path even after F1's summary fallback lands
    for request_changes verdicts."""
    config = OrchestratorConfig()
    paths = runtime_paths(tmp_path, config.runtime.state_dir)
    fake_gh = FakeGitHub()
    app = OrchestratorApp(tmp_path, paths, config, fake_gh)

    pr_dir = paths.prs / "pr-456"
    pr_dir.mkdir(parents=True, exist_ok=True)
    (pr_dir / "review-decision.json").write_text(
        json.dumps({"decision": "approved", "summary": "lgtm"}),
        encoding="utf-8",
    )
    pr = {
        "number": 456,
        "title": "Fix #123: search",
        "url": "https://example.test/pull/456",
        "headRefName": "agent/issue-123-fix-search",
    }
    operational_note = (
        "The PR branch has a merge conflict. Merge the base branch and resolve. "
        "The code changes are already approved; do not re-litigate the review."
    )
    app._write_rework_prompt(pr, 123, operational_note)

    brief = (pr_dir / "rework-prompt.md").read_text(encoding="utf-8")
    norm_brief = _normalize_ws(brief)
    assert "## Required changes" not in brief
    assert "Address every Critical and Important finding directly" not in norm_brief
    # The demoted base-merge bullet is still present for the route that
    # genuinely needs it (the merge-conflict rework path) -- demoted, not
    # deleted.
    assert "If your branch is behind its base or the PR shows a merge conflict" in norm_brief


def test_detect_and_handle_stalled_reviews_aggregates_same_pass_events(
    monkeypatch, tmp_path: Path
) -> None:
    """Issue #525: multiple stalled reviewer claims in one pass become one sweep event."""
    from charlie_work.worker import WorkerView

    repo_root = tmp_path / "repo"
    repo_root.mkdir()
    reviews_dir = tmp_path / "reviews"
    state_file = tmp_path / "state.json"
    config = OrchestratorConfig()

    prs = [100, 200, 300]
    old = (datetime.now(UTC) - timedelta(hours=1)).isoformat().replace("+00:00", "Z")
    state = empty_state()
    for pr in prs:
        state["prs"][str(pr)] = {
            "number": pr,
            "review_dispatch_status": "review_dispatch_dispatched",
            "review_dispatched_at": old,
            "reviewer_pid": 99999,
            "reviewer_process_start_time": 1.0,
        }
    save_state(state_file, state)

    for pr in prs:
        _make_dead_review_sidecar(reviews_dir, pr, "no verdict")

    monkeypatch.setattr(WorkerView, "is_alive", lambda self: False)
    monkeypatch.setattr("charlie_work.workflow.is_pid_alive", lambda *_: False)
    monkeypatch.setattr("charlie_work.workflow.remove_review_checkout", lambda *a, **k: True)

    stalled = _detect_and_handle_stalled_reviews(reviews_dir, state_file, config, repo_root)

    assert {entry["pr"] for entry in stalled} == set(prs)
    state_after = load_state(state_file)
    events = state_after["events"]
    sweep = [e for e in events if e.get("kind") == "review_dispatch_stalled_sweep"]
    assert len(sweep) == 1
    assert sweep[0]["payload"]["count"] == len(prs)
    assert set(sweep[0]["payload"]["pr_numbers"]) == set(prs)


